#include "sync_batch_norm.cuh"
#include "mgt/batch_norm.hpp"
#include "mgt_cuda/allreduce_nccl.cuh"
#include <cuda_runtime.h>
#include <cmath>
#include <cstdlib>
#include <vector>
int main(){constexpr int R=3,C=2,S=4;float x[R*S]={1,2,99,99,3,6,99,99,8,4,99,99},dy[R*S]={1,-1,77,77,2,.5f,77,77,-.5f,3,77,77},g[C]={.7f,1.2f},b[C]={.1f,-.3f};std::vector<float> px,pd;for(int r=0;r<R;r++)for(int c=0;c<C;c++){px.push_back(x[r*S+c]);pd.push_back(dy[r*S+c]);}float rm[C]={},rv[C]={1,1},cy[R*C],cdx[R*C],cdg[C],cdb[C];mgt::BatchNormCache cache;mgt::batch_norm_forward_cpu(px.data(),R,C,g,b,rm,rv,.1f,1e-5f,true,cy,&cache);mgt::batch_norm_backward_cpu(pd.data(),cache,g,cdx,cdg,cdb);float *dx0,*ddy,*dg,*db,*drm,*drv,*dout,*dmean,*dinv,*dxh,*ddx,*ddg,*ddb,*dw;cudaMalloc(&dx0,sizeof(x));cudaMalloc(&ddy,sizeof(dy));cudaMalloc(&dout,sizeof(x));cudaMalloc(&dxh,sizeof(x));cudaMalloc(&ddx,sizeof(x));float**v[]={&dg,&db,&drm,&drv,&dmean,&dinv,&ddg,&ddb};for(auto q:v)cudaMalloc(q,C*4);cudaMalloc(&dw,2*C*4);cudaMemcpy(dx0,x,sizeof(x),cudaMemcpyHostToDevice);cudaMemcpy(ddy,dy,sizeof(dy),cudaMemcpyHostToDevice);cudaMemcpy(dg,g,sizeof(g),cudaMemcpyHostToDevice);cudaMemcpy(db,b,sizeof(b),cudaMemcpyHostToDevice);cudaMemset(drm,0,C*4);cudaMemcpy(drv,rv,sizeof(rv),cudaMemcpyHostToDevice);mgt_cuda::NcclRankContext* ctx=nullptr;if(mgt_cuda::CreateNcclSingleRankContext(0,&ctx)!=mgt::Status::kOk)return 1;if(mgt_cuda::LaunchStridedSyncBatchNormForward(dx0,R,R,C,S,dg,db,drm,drv,.1f,1e-5f,dout,dmean,dinv,dxh,dw,ctx,0)!=mgt::Status::kOk||mgt_cuda::LaunchStridedSyncBatchNormBackward(ddy,R,R,C,S,dg,dinv,dxh,ddx,ddg,ddb,dw,ctx,0)!=mgt::Status::kOk||cudaDeviceSynchronize()!=cudaSuccess)return 1;float gy[R*S],gdx[R*S],gdg[C],gdb[C];cudaMemcpy(gy,dout,sizeof(gy),cudaMemcpyDeviceToHost);cudaMemcpy(gdx,ddx,sizeof(gdx),cudaMemcpyDeviceToHost);cudaMemcpy(gdg,ddg,sizeof(gdg),cudaMemcpyDeviceToHost);cudaMemcpy(gdb,ddb,sizeof(gdb),cudaMemcpyDeviceToHost);for(int r=0;r<R;r++)for(int c=0;c<C;c++)if(std::fabs(gy[r*S+c]-cy[r*C+c])>2e-4f||std::fabs(gdx[r*S+c]-cdx[r*C+c])>2e-4f)return 1;for(int c=0;c<C;c++)if(std::fabs(gdg[c]-cdg[c])>2e-4f||std::fabs(gdb[c]-cdb[c])>2e-4f)return 1;return mgt_cuda::DestroyNcclRankContext(ctx)==mgt::Status::kOk?0:1;}